第2题 在C++中，与 for(int i = 10; i < 20; i += 2) cout << i；输出结果相同的是( )。
□ A. for(int i = 10; i < 19; i += 2) cout << i;
□ B. for(int i = 11; i < 19; i += 2) cout << i;
□ C. for(int i = 10; i < 21; i += 2) cout << i;
□ D. 以上均不对

cin >> N;
newNum = 0;
while(N){
    newNum = newNum * 10 + N % 10;
    N = N / 10;
}
if(newNum == N)
    cout << N << "为对称数";
□ A.代码没有语法错误，如果N为对称数，第8行将能正确输出。
□ B.代码没有语法错误，但如果N为负数，将导致死循环。
□ C.代码存在语法错误，程序不能被执行。
□ D.代码没有语法错误，但不能达到预期目标，因为循环结束N总为0。

cin >> N;
for(i = 2; i < N/2; i++)
    if(N % i == 0){
    cout << N << " 不是质数";
    break;
    }
    if(i >= N/2)
    cout << N << " 是质数";

N=100;
while (N > 0)
    if (N % 2)
    break;
else if (N % 3 == 0)
    N -= 5;
else
    N -= 20;
cout << N;

